4	:root {
5	  /* Typography */
6	  --font-sans: "Geist Variable", "Geist", -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif;
7	  --font-mono: "Geist Mono Variable", "Geist Mono", "SFMono-Regular", "Cascadia Mono", Menlo, Consolas, monospace;
8	
9	  /* Font sizes and line heights */
10	  --text-2xs: 11px;
11	  --leading-2xs: 16px;
12	  --text-xs: 12px;
13	  --leading-xs: 18px;
14	  --text-sm: 13px;
15	  --leading-sm: 20px;
16	  --text-base: 14px;
17	  --leading-base: 22px;
18	  --text-md: 15px;
19	  --leading-md: 24px;
20	  --text-lg: 18px;
21	  --leading-lg: 26px;
22	  --text-xl: 20px;
23	  --leading-xl: 28px;
24	  --text-2xl: 24px;
25	  --leading-2xl: 32px;
26	
27	  /* Spacing 4px scale */
28	  --space-0: 0px;
29	  --space-1: 4px;
30	  --space-1-5: 6px;
31	  --space-2: 8px;
32	  --space-2-5: 10px;
33	  --space-3: 12px;
34	  --space-4: 16px;
35	  --space-5: 20px;
36	  --space-6: 24px;
37	  --space-8: 32px;
38	  --space-10: 40px;
39	  --space-12: 48px;
40	
41	  /* Uniform Radius Scale */
42	  --radius-xs: 4px;
43	  --radius-sm: 6px;
44	  --radius-md: 8px;
45	  --radius-card: 12px;
46	  --radius-lg: 14px;
47	  --radius-xl: 18px;
48	  --radius-full: 9999px;
49	
50	  /* Layout Dimensions */
51	  --rail-width: 264px;
52	  --rail-width-compact: 232px;
53	  --header-height: 52px;
54	  --inspector-width: 380px;
55	  --inspector-width-compact: 320px;
56	  --control-height: 34px;
57	  --control-height-sm: 28px;
58	  --control-height-lg: 40px;
59	  --reading-measure: 780px;
60	  /* Compact phone navigation bar; also the offset reserved for it in the
61	     stacked mobile layout so the reading flow never hides behind it. */
62	  --mobile-nav-height: 56px;
63	
64	  /* Control geometry */
65	  --icon-size: 30px;
66	  --icon-size-touch: 44px;
67	  --touch-min-target: 44px;
68	
69	  /* Quiet control radius */
70	  --radius-quiet: var(--radius-sm);
71	
72	  /* Narrow / touch prose metrics (DESIGN.md §3: 17px / 1.75 on touch) */
73	  --prose-size-narrow: 17px;
74	  --prose-leading-narrow: 1.75;
75	  --text-touch: 16px;
76	  --leading-touch: 28px;
77	
78	  /* Focus ring offset */
79	  --focus-ring-offset: 2px;
80	  --transition-fast: 120ms cubic-bezier(0.16, 1, 0.3, 1);
81	  --transition-normal: 180ms cubic-bezier(0.16, 1, 0.3, 1);
82	}
