84	:root,
85	[data-theme="light"] {
86	  color-scheme: light;
87	
88	  /* Crisp Neutral Surfaces (Zinc/Slate modern architecture) */
89	  --canvas-bg: #ffffff;
90	  --sidebar-bg: #f8f9fa;
91	  --surface-shell: #f1f3f5;
92	  --surface-elevated: #ffffff;
93	  --surface-soft: #f3f4f6;
94	  --surface-hover: #e9ecef;
95	  --surface-active: #dee2e6;
96	  --surface-selected: #e3e8ee;
97	
98	  /* Typography Colors */
99	  --text-primary: #111827;
100	  --text-secondary: #4b5563;
101	  --text-muted: #6b7280;
102	  --text-disabled: #9ca3af;
103	  --text-tertiary: #6b7280;
104	
105	  /* Borders & Dividers */
106	  --border-subtle: #e5e7eb;
107	  --border-control: #d1d5db;
108	  --border-hover: #9ca3af;
109	
110	  /* Brand Accents */
111	  --accent-sage: #059669;
112	  --accent-sage-soft: #ecfdf5;
113	  --accent: #059669;
114	  --focus-ring: #10b981;
115	  --link: #059669;
116	
117	  /* States — inks meet ≥ 4.5:1 against their own tinted surfaces (DESIGN.md §2):
118	     success 5.75:1, warning 5.21:1, error 5.83:1. The previous bright
119	     emerald/amber/red inks measured 2.41 / 3.07 / 3.44:1 on these backgrounds
120	     and could not carry status text. */
121	  --success: #226d40;
122	  --success-bg: #edf7ef;
123	  --success-border: #aee4be;
124	
125	  --warning: #975a06;
126	  --warning-bg: #fef7e9;
127	  --warning-border: #fedf89;
128	
129	  --error: #b82420;
130	  --error-bg: #fef3f2;
131	  --error-border: #fecdca;
132	
133	  /* High contrast call-to-action */
134	  --run-bg: #111827;
135	  --run-ink: #ffffff;
136	  --run-hover: #1f2937;
137	  --run-active: #030712;
138	
139	  /* Modern Subtle Drop Shadows */
140	  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
141	  --shadow-card: 0 1px 3px 0 rgba(0, 0, 0, 0.08), 0 1px 2px -1px rgba(0, 0, 0, 0.08);
142	  --shadow-composer: 0 4px 16px -2px rgba(0, 0, 0, 0.08), 0 2px 6px -2px rgba(0, 0, 0, 0.04);
143	  --shadow-overlay: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.1);
144	  --shadow-dropdown: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.05);
145	}
