292	@media (max-width: 1000px) {
293	  .wb-app .wb-new-session-intro,
294	  .wb-app .wb-new-session .composer-fresh {
295	    width: calc(100% - 2 * var(--space-4));
296	  }
297	  .wb-app .wb-new-session-intro {
298	    margin-top: var(--space-4);
299	  }
300	  .wb-app .wb-new-session .composer-fresh {
301	    margin-bottom: var(--space-3);
302	  }
303	  .wb-app .composer-dropdown-trigger,
304	  .wb-app .composer-project-trigger {
305	    min-height: var(--touch-min-target);
306	  }
307	  .wb-app .composer-dropdown-item,
