312	/* Short viewports: geometry-only. The single vertical scrollbar stays with
313	   the reading-flow viewport; the duplicate `overflow-y` that used to live
314	   here (and in components/workbench/new-session.css) created nested scroll
315	   containers on the same element and was removed from both sheets. */
316	@media (max-height: 700px) {
317	  .wb-app .wb-new-session-intro {
318	    margin-top: var(--space-4);
319	  }
320	  .wb-app .wb-new-session .composer-fresh {
321	    margin-bottom: var(--space-4);
322	  }
323	}
