/* When dual action buttons appear in running state, smoothly animate cancel button from right to left */
.wb-app .composer-split .composer-submit-col.is-dual .composer-cancel {
  animation: composer-cancel-shift-left 0.32s cubic-bezier(0.16, 1, 0.3, 1) both;
  will-change: transform;
}

@keyframes composer-cancel-shift-left {
  0% {
    transform: translateX(50px);
  }
  100% {
    transform: translateX(0);
  }
}

/* When returning from dual action back to single action, smoothly slide cancel button back to the right */
.wb-app .composer-split .composer-submit-col.is-rebounding:not(.is-dual) .composer-cancel {
  animation: composer-cancel-shift-right 0.25s cubic-bezier(0.16, 1, 0.3, 1) both;
  will-change: transform;
}

@keyframes composer-cancel-shift-right {
  0% {
    transform: translateX(-50px);
  }
  100% {
    transform: translateX(0);
  }
}

/* Dual action send container with smooth entry animation */
.composer-dual-send-wrap {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
  animation: composer-dual-send-in 0.28s cubic-bezier(0.16, 1, 0.3, 1) both;
  will-change: transform, opacity;
}

@keyframes composer-dual-send-in {
  0% {
    opacity: 0;
    transform: scale(0.92) translateX(8px);
  }
  100% {
    opacity: 1;
    transform: scale(1) translateX(0);
  }
}

