def lin(c):
    c = c/255.0
    return c/12.92 if c <= 0.04045 else ((c+0.055)/1.055)**2.4
def L(h):
    h = h.lstrip('#')
    r,g,b = [int(h[i:i+2],16) for i in (0,2,4)]
    return 0.2126*lin(r) + 0.7152*lin(g) + 0.0722*lin(b)
def ratio(a,b):
    la,lb = L(a), L(b)
    hi,lo = max(la,lb), min(la,lb)
    return (hi+0.05)/(lo+0.05)
def blend(fg,bg,alpha):
    f=fg.lstrip('#'); b=bg.lstrip('#')
    out=''
    for i in (0,2,4):
        c = round(int(f[i:i+2],16)*alpha + int(b[i:i+2],16)*(1-alpha))
        out += f'{c:02x}'
    return '#'+out

light = {
 'canvas':'#faf9f6','sidebar':'#f2f1ed','elevated':'#ffffff','soft':'#f0efeb',
 'hover':'#e8e6e0','active':'#dedbd3','selected':'#e6e3dc',
