 'hover':'#30302e','active':'#3a3936','selected':'#343330',
 'primary':'#eeede8','secondary':'#aaa79f','muted':'#aaa79f',
 'accent':'#dc9477','success':'#34d399','warning':'#fbbf24','error':'#f87171',
}
surfaces = ['canvas','sidebar','elevated','soft','hover','active','selected']
inks = ['primary','secondary','muted']

for name, pal in (('LIGHT', light), ('DARK', dark)):
    print(f'\n### {name} — ink x surface')
    print('| ink \\ surface | ' + ' | '.join(surfaces) + ' |')
    print('|---|' + '---|'*len(surfaces))
    for ink in inks:
        row = []
        for s in surfaces:
            r = ratio(pal[ink], pal[s])
            mark = '' if r >= 4.5 else (' ⚠' if r >= 3.5 else ' ✗')
            row.append(f'{r:.2f}{mark}')
        print(f'| {ink} `{pal[ink]}` | ' + ' | '.join(row) + ' |')

print('\n### accent on surfaces')
for name, pal in (('LIGHT', light), ('DARK', dark)):
    for s in ['canvas','elevated','soft','selected']:
        r = ratio(pal['accent'], pal[s])
        print(f'{name} accent on {s}: {r:.2f}' + ('' if r>=4.5 else '  FAIL'))

print('\n### semantic ink on own tinted background')
light_sem = {'success':('#226d40','#edf7ef'),'warning':('#975a06','#fef7e9'),'error':('#b82420','#fef3f2')}
dark_sem = {'success':('#34d399','#064e3b'),'warning':('#fbbf24','#451a03'),'error':('#f87171','#450a0a')}
for name, sem in (('LIGHT', light_sem), ('DARK', dark_sem)):
    for k,(fg,bg) in sem.items():
        print(f'{name} {k}: {ratio(fg,bg):.2f}')

print('\n### white on accent (dark)')
print('dark  #ffffff on #dc9477:', round(ratio('#ffffff','#dc9477'),2))
