print('\n### borders vs surfaces (UI 3:1)')
for name,(b,cs) in (('LIGHT', ('#e5e3dc','#ffffff','#faf9f6')), ('DARK', ('#2b2b28','#222221','#171716'))):
    print(f'{name} border-subtle vs elevated: {ratio(b,cs[1]):.2f}; vs canvas: {ratio(b,cs[2]):.2f}')
for name,(b,cs) in (('LIGHT', ('#d1cec5','#ffffff','#faf9f6')), ('DARK', ('#3d3c37','#222221','#171716'))):
    print(f'{name} border-control vs elevated: {ratio(b,cs[1]):.2f}; vs canvas: {ratio(b,cs[2]):.2f}')

