python3 - <<'PY'
import re, glob, os

targets = ['inspector-section','inspector-card','settings-card','settings-entry','agent-profile-card',
           'agent-editor-section','mcp-card','plugin-card','advisor-card','child-session-card',
           'approval-panel','diff-viewer','code-block','chart-card','message-user','composer-surface',
           'tool-disclosure-header','settings-panel-card','inspector-plan-summary-card']

props = ('background','border','border-radius','box-shadow','padding')
results = {}
for path in glob.glob('**/*.css', recursive=True):
    src = open(path, encoding='utf-8').read()
    # strip comments
    src_nc = re.sub(r'/\*.*?\*/', '', src, flags=re.S)
    for m in re.finditer(r'([^{}]+)\{([^{}]*)\}', src_nc):
        sel, body = m.group(1).strip(), m.group(2)
        for t in targets:
            # selector ends with the class as its own class token
            if re.search(r'(^|[\s,>+~])\.' + re.escape(t) + r'(\s|,|$|:|\.)', sel) and sel.splitlines()[-1].strip().endswith(t):
                pass
            last = [s.strip() for s in sel.replace('\n',' ').split(',') if s.strip()]
            if not any(re.search(r'\.' + re.escape(t) + r'$', s) for s in last):
                continue
            decls = {}
            for line in body.split(';'):
                if ':' not in line: continue
                k, v = line.split(':', 1)
                k = k.strip(); v = v.strip()
                if k in props or k.startswith('border-'):
                    decls[k] = v
            if decls:
                results.setdefault(t, []).append((path, sel.replace('\n',' ').strip()[:70], decls))

for t in targets:
    rows = results.get(t, [])
    print(f'\n### {t}  ({len(rows)} rules)')
    for path, sel, d in rows[:4]:
        print(f'  {path}  [{sel}]')
        for k, v in d.items():
            print(f'      {k}: {v}')
