const browser = await chromium.launch({ executablePath: "/usr/bin/google-chrome-stable" });
const page = await browser.newPage();
await page.setContent(`<html><head><style>
@import url("file:///home/ling/services/desktop-harness/repos/forge-web-ui/node_modules/@fontsource-variable/geist/index.css");
body{margin:0;font-family:"Geist Variable",sans-serif}
#probe{font-size:16px;line-height:1.75;width:760px;font-weight:400}
</style></head><body><div id="probe">x</div></body></html>`);
await page.waitForTimeout(600);
const r = await page.evaluate(() => {
  const p = document.getElementById("probe");
  const measure = (text) => {
    p.textContent = text;
    const range = document.createRange();
    range.selectNodeContents(p);
    const w = range.getBoundingClientRect().width;
    return { text: text.slice(0, 24), width: w, chars: text.length };
  };
  const latin = "The quick brown fox jumps over the lazy dog while the system "
    .repeat(4);
  const mixed = "当一个工具调用返回较长的输出时，界面需要把它折叠成单行摘要，"
    .repeat(2);
  const l = measure(latin);
  const c = measure(mixed);
  return {
    latinPxPerChar: +(l.width / l.chars).toFixed(2),
    latinCpl: +(760 / (l.width / l.chars)).toFixed(1),
    cjkPxPerChar: +(c.width / c.chars).toFixed(2),
    cjkCpl: +(760 / (c.width / c.chars)).toFixed(1),
  };
});
console.log(JSON.stringify(r, null, 2));
await browser.close();
EOF
